#include <vector>
#include <algorithm>

class Solution {
    int linearRob(const std::vector<int>& arr, int k) {
        int m = arr.size();
        std::vector<std::vector<int>> dp(m + 1, std::vector<int>(k + 1, 0));
        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= k; ++j) {
                int take = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                int skip = dp[i - 1][j];
                dp[i][j] = std::max(take, skip);
            }
        }
        return dp[m][k];
    }
public:
    int maxSizeSlices(std::vector<int>& slices) {
        int k = slices.size() / 3;
        std::vector<int> arr1(slices.begin(), slices.end() - 1);
        std::vector<int> arr2(slices.begin() + 1, slices.end());
        return std::max(linearRob(arr1, k), linearRob(arr2, k));
    }
};

import java.util.*;

class Solution {
    private int linearRob(int[] arr, int k) {
        int m = arr.length;
        int[][] dp = new int[m + 1][k + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= k; j++) {
                int take = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                int skip = dp[i - 1][j];
                dp[i][j] = Math.max(take, skip);
            }
        }
        return dp[m][k];
    }
    public int maxSizeSlices(int[] slices) {
        int k = slices.length / 3;
        int[] arr1 = Arrays.copyOfRange(slices, 0, slices.length - 1);
        int[] arr2 = Arrays.copyOfRange(slices, 1, slices.length);
        return Math.max(linearRob(arr1, k), linearRob(arr2, k));
    }
}

var maxSizeSlices = function(slices) {
    const k = Math.floor(slices.length / 3);
    const linearRob = (arr) => {
        const m = arr.length;
        const dp = Array.from({ length: m + 1 }, () => new Array(k + 1).fill(0));
        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= k; j++) {
                const take = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                const skip = dp[i - 1][j];
                dp[i][j] = Math.max(take, skip);
            }
        }
        return dp[m][k];
    };
    return Math.max(linearRob(slices.slice(0, -1)), linearRob(slices.slice(1)));
};
